source_context:
11:       - assert: { that: "vault_init.rc == 0" }
12:       when: "vault_init is not changed"
13:     - block:
14:       - assert: { that: "'keys' in vault_init" }
15:       - assert: { that: "'root_token' in vault_init" }
16:       - assert: { that: "vault_init.rc == 0" }
17:       - set_fact:
18:           vault_keys: "{{vault_init['keys'] | join(' ')}}"
19:       - name: Unseal the vault
20:         hashivault_unseal:
21:           keys: '{{vault_keys}}'
22:         register: 'vault_unseal'
23:       - assert: { that: "vault_unseal is changed" }
24:       - assert: { that: "vault_unseal.status.progress == 0" }
25:       - assert: { that: "vault_unseal.status.sealed == False" }
26:       - assert: { that: "vault_unseal.rc == 0" }
27:       - template:
28:           src: "{{playbook_dir}}/templates/vaultenv.sh.j2"
29:           dest: "{{playbook_dir}}/vaultenv.sh"
30:           mode: 0700
